            const trigger = "localstorage, indexeddb, \u6C38\u7D9A\u5316, \u30AD\u30E3\u30C3\u30B7\u30E5, \u4FDD\u5B58, \u540C\u671F, \u30B9\u30C8\u30EC\u30FC\u30B8";
